{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Ensure that Cloud SQL database Instances are not open to the world",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The database instance is exposed to the internet via an authorized network with a CIDR of 0.0.0.0/0."
    },
    {
      "check_id": "CKV_GCP_60",
      "title": "Ensure Cloud SQL database does not have public IP",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The database instance has a public IP address enabled."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The database instance does not require SSL for incoming connections."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "Ensure PostgreSQL database 'log_checkpoints' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_checkpoints' flag is not set to 'on', which may lead to insufficient logging."
    },
    {
      "check_id": "CKV_GCP_52",
      "title": "Ensure PostgreSQL database 'log_connections' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_connections' flag is not set to 'on', which may lead to insufficient logging."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Ensure PostgreSQL database 'log_disconnections' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_disconnections' flag is not set to 'on', which may lead to insufficient logging."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is not set to 'on', which may lead to insufficient logging."
    },
    {
      "check_id": "CKV2_GCP_13",
      "title": "Ensure PostgreSQL database flag 'log_duration' is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_duration' flag is not set to 'on', which may lead to insufficient logging."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = false\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_duration\"\n      value = \"on\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Removed public IP exposure, enabled SSL requirement, added various PostgreSQL logging flags, and enabled deletion protection."
}
